<?php
declare(strict_types=1); namespace Theobroma\OneC\Http;
use Theobroma\OneC\Import\ImportResult;
final class IncomingExchangeService {private \Closure$importer;public function __construct(private readonly bool$enabled,private readonly ExchangeFileStore$store,callable$importer){$this->importer=$importer(...);}public function handle(string$mode,string$filename,string$body):ExchangeResponse{if(!$this->enabled)return new ExchangeResponse(403,"failure\nImport direction disabled");try{return match($mode){'file'=>$this->file($filename,$body),'import'=>$this->import($filename),default=>new ExchangeResponse(400,"failure\nUnsupported incoming mode")};}catch(\InvalidArgumentException|\LengthException$e){return new ExchangeResponse(400,"failure\n".$e->getMessage());}catch(\Throwable){return new ExchangeResponse(500,"failure\nIncoming exchange failed");}}private function file(string$name,string$body):ExchangeResponse{$this->store->append($name,$body);return new ExchangeResponse(200,'success');}private function import(string$name):ExchangeResponse{try{$result=($this->importer)($this->store->read($name));if(!$result instanceof ImportResult)throw new \RuntimeException('Invalid importer result');return new ExchangeResponse(200,"success\napplied={$result->applied}\nskipped={$result->skipped}\nambiguous={$result->ambiguous}\nerrors={$result->errors}");}finally{$this->store->delete($name);}}}
